import type {
  PaymentProviderId,
  PaymentRequest,
  PaymentResult,
  PaymentRefundRequest,
  PaymentRefundResult,
  PaymentSessionStatus,
} from './paymentTypes'
import type { PaymentProvider, PaymentProviderConfig } from './paymentProvider'

function generateId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `pay_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`
}

export class MockPaymentProvider implements PaymentProvider {
  readonly providerId: PaymentProviderId = 'mock'
  readonly displayName: string = 'Mock Payment Gateway'

  private sessions: Map<string, { status: PaymentSessionStatus; amount: number; currency: string; transactionId: string | null }> = new Map()

  constructor(config: PaymentProviderConfig | null = null) {
    void config
  }

  async createPaymentSession(request: PaymentRequest): Promise<PaymentResult> {
    const sessionId = generateId()
    const status: PaymentSessionStatus = 'pending'
    this.sessions.set(sessionId, {
      status,
      amount: request.amount,
      currency: request.currency,
      transactionId: null,
    })

    return {
      success: true,
      providerId: 'mock',
      paymentSessionId: sessionId,
      status,
      providerReference: `MOCK-REF-${sessionId.slice(0, 8).toUpperCase()}`,
      authorizationCode: null,
      transactionId: null,
      message: 'Mock payment session created',
      redirectUrl: null,
      paidAt: null,
      metadata: { mock: true, requestAmount: request.amount },
    }
  }

  async authorizePayment(paymentSessionId: string): Promise<PaymentResult> {
    const session = this.sessions.get(paymentSessionId)
    if (!session) {
      return this.failureResult(paymentSessionId, 'Payment session not found')
    }
    if (session.status === 'paid') {
      return this.failureResult(paymentSessionId, 'Payment already captured')
    }
    if (session.status === 'cancelled' || session.status === 'expired') {
      return this.failureResult(paymentSessionId, `Cannot authorize in status: ${session.status}`)
    }

    const authCode = `AUTH-${Date.now().toString(36).toUpperCase()}`
    session.status = 'authorized'
    session.transactionId = `TXN-${paymentSessionId.slice(0, 8).toUpperCase()}`

    return {
      success: true,
      providerId: 'mock',
      paymentSessionId,
      status: 'authorized',
      providerReference: `MOCK-REF-${paymentSessionId.slice(0, 8).toUpperCase()}`,
      authorizationCode: authCode,
      transactionId: session.transactionId,
      message: 'Payment authorized (mock)',
      redirectUrl: null,
      paidAt: null,
      metadata: { mock: true, authorized: true },
    }
  }

  async capturePayment(paymentSessionId: string): Promise<PaymentResult> {
    const session = this.sessions.get(paymentSessionId)
    if (!session) {
      return this.failureResult(paymentSessionId, 'Payment session not found')
    }
    if (session.status !== 'authorized' && session.status !== 'pending') {
      return this.failureResult(paymentSessionId, `Cannot capture in status: ${session.status}`)
    }

    session.status = 'paid'
    const paidAt = new Date().toISOString()

    return {
      success: true,
      providerId: 'mock',
      paymentSessionId,
      status: 'paid',
      providerReference: `MOCK-REF-${paymentSessionId.slice(0, 8).toUpperCase()}`,
      authorizationCode: `AUTH-${Date.now().toString(36).toUpperCase()}`,
      transactionId: session.transactionId ?? `TXN-${paymentSessionId.slice(0, 8).toUpperCase()}`,
      message: 'Payment captured successfully (mock)',
      redirectUrl: null,
      paidAt,
      metadata: { mock: true, captured: true },
    }
  }

  async refundPayment(request: PaymentRefundRequest): Promise<PaymentRefundResult> {
    const session = this.sessions.get(request.paymentId)
    if (!session) {
      return {
        success: false,
        refundId: null,
        refundedAmount: 0,
        message: 'Payment session not found',
      }
    }
    if (session.status !== 'paid') {
      return {
        success: false,
        refundId: null,
        refundedAmount: 0,
        message: `Cannot refund in status: ${session.status}`,
      }
    }

    session.status = 'refunded'
    return {
      success: true,
      refundId: `RFD-${Date.now().toString(36).toUpperCase()}`,
      refundedAmount: request.amount,
      message: 'Refund processed (mock)',
    }
  }

  async getPaymentStatus(paymentSessionId: string): Promise<PaymentSessionStatus | null> {
    const session = this.sessions.get(paymentSessionId)
    return session ? session.status : null
  }

  private failureResult(paymentSessionId: string, message: string): PaymentResult {
    return {
      success: false,
      providerId: 'mock',
      paymentSessionId,
      status: 'failed',
      providerReference: null,
      authorizationCode: null,
      transactionId: null,
      message,
      redirectUrl: null,
      paidAt: null,
      metadata: { mock: true },
    }
  }
}

import type {
  RahhalOrder,
  OrderStatus,
  CheckoutCart,
  CheckoutItem,
  TravelerInfo,
} from './checkoutTypes'
import type { PaymentSession } from './paymentTypes'

function generateId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `ord_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`
}

function generateOrderNumber(): string {
  const now = new Date()
  const ymd = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}`
  const rand = Math.random().toString(36).slice(2, 7).toUpperCase()
  return `RH-${ymd}-${rand}`
}

function generateBookingNumber(): string {
  const rand = Math.random().toString(36).slice(2, 10).toUpperCase()
  return `BK-${rand}`
}

function generateCustomerReference(): string {
  const rand = Math.random().toString(36).slice(2, 8).toUpperCase()
  return `CUST-${rand}`
}

export interface CreateOrderInput {
  userId: string
  travelSessionId: string | null
  cart: CheckoutCart
  travelers: TravelerInfo[]
  couponCode: string | null
  discountAmount: number
}

const orders: Map<string, RahhalOrder> = new Map()
const userOrders: Map<string, string[]> = new Map()

export function createOrder(input: CreateOrderInput): RahhalOrder {
  const now = new Date().toISOString()
  const order: RahhalOrder = {
    id: generateId(),
    orderNumber: generateOrderNumber(),
    bookingNumber: generateBookingNumber(),
    customerReference: generateCustomerReference(),
    userId: input.userId,
    travelSessionId: input.travelSessionId,
    status: 'created',
    cart: { ...input.cart, items: input.cart.items.map(i => ({ ...i, metadata: { ...i.metadata } })) },
    travelers: input.travelers.map(t => ({ ...t })),
    couponCode: input.couponCode,
    discountAmount: input.discountAmount,
    paymentSessionId: null,
    paymentProvider: null,
    paidAt: null,
    confirmedAt: null,
    invoiceNumber: null,
    itineraryId: null,
    createdAt: now,
    updatedAt: now,
  }
  orders.set(order.id, order)
  const userOrderIds = userOrders.get(input.userId) ?? []
  userOrderIds.push(order.id)
  userOrders.set(input.userId, userOrderIds)
  return { ...order, cart: { ...order.cart, items: order.cart.items.map(i => ({ ...i, metadata: { ...i.metadata } })) }, travelers: order.travelers.map(t => ({ ...t })) }
}

export function getOrder(orderId: string): RahhalOrder | null {
  const order = orders.get(orderId)
  if (!order) return null
  return cloneOrder(order)
}

export function getOrderByNumber(orderNumber: string): RahhalOrder | null {
  for (const order of orders.values()) {
    if (order.orderNumber === orderNumber) return cloneOrder(order)
  }
  return null
}

export function updateOrderStatus(orderId: string, status: OrderStatus): RahhalOrder | null {
  const order = orders.get(orderId)
  if (!order) return null
  order.status = status
  order.updatedAt = new Date().toISOString()
  if (status === 'paid') order.paidAt = order.paidAt ?? new Date().toISOString()
  if (status === 'confirmed') order.confirmedAt = order.confirmedAt ?? new Date().toISOString()
  return cloneOrder(order)
}

export function attachPaymentSession(orderId: string, paymentSession: PaymentSession): RahhalOrder | null {
  const order = orders.get(orderId)
  if (!order) return null
  order.paymentSessionId = paymentSession.id
  order.paymentProvider = paymentSession.providerId
  order.updatedAt = new Date().toISOString()
  return cloneOrder(order)
}

export function markOrderPaid(orderId: string, invoiceNumber: string): RahhalOrder | null {
  const order = orders.get(orderId)
  if (!order) return null
  order.status = 'paid'
  order.paidAt = new Date().toISOString()
  order.invoiceNumber = invoiceNumber
  order.updatedAt = new Date().toISOString()
  return cloneOrder(order)
}

export function markOrderConfirmed(orderId: string, itineraryId: string): RahhalOrder | null {
  const order = orders.get(orderId)
  if (!order) return null
  order.status = 'confirmed'
  order.confirmedAt = new Date().toISOString()
  order.itineraryId = itineraryId
  order.updatedAt = new Date().toISOString()
  return cloneOrder(order)
}

export function listOrdersByUser(userId: string): RahhalOrder[] {
  const ids = userOrders.get(userId) ?? []
  return ids
    .map(id => orders.get(id))
    .filter((o): o is RahhalOrder => o !== null)
    .map(cloneOrder)
}

export function listAllOrders(): RahhalOrder[] {
  return Array.from(orders.values()).map(cloneOrder)
}

export function clearAllOrders(): void {
  orders.clear()
  userOrders.clear()
}

function cloneOrder(order: RahhalOrder): RahhalOrder {
  return {
    ...order,
    cart: {
      ...order.cart,
      items: order.cart.items.map(i => ({ ...i, metadata: { ...i.metadata } })),
    },
    travelers: order.travelers.map(t => ({ ...t })),
  }
}

export function generateInvoiceNumber(_order: RahhalOrder): string {
  const year = new Date().getFullYear()
  const seq = Math.random().toString(36).slice(2, 8).toUpperCase()
  return `INV-${year}-${seq}`
}

export function generateItineraryId(order: RahhalOrder): string {
  return `ITIN-${order.orderNumber}`
}

export function buildCart(items: CheckoutItem[], currency: string, _couponCode: string | null, discountAmount: number): CheckoutCart {
  const subtotal = items.reduce((sum, item) => sum + item.price, 0)
  const taxes = Math.round(subtotal * 0.15 * 100) / 100
  const fees = 0
  const total = subtotal + taxes + fees - discountAmount
  return {
    items: items.map(i => ({ ...i, metadata: { ...i.metadata } })),
    subtotal,
    taxes,
    fees,
    discount: discountAmount,
    total,
    currency,
  }
}

import type { PaymentProvider, PaymentProviderConfig, PaymentProviderType } from './paymentProvider'
import { defaultProviderConfig } from './paymentProvider'
import { MockPaymentProvider } from './mockPaymentProvider'

const instances: Map<PaymentProviderType, PaymentProvider> = new Map()

export function createPaymentProvider(
  type: PaymentProviderType,
  config: PaymentProviderConfig | null = null,
): PaymentProvider {
  const cached = instances.get(type)
  if (cached) return cached

  const cfg = config ?? defaultProviderConfig()

  let provider: PaymentProvider
  switch (type) {
    case 'mock':
      provider = new MockPaymentProvider(cfg)
      break
    case 'hyperpay':
      throw new Error('HyperPay provider not yet implemented. Use "mock" for development.')
    case 'moyasar':
      throw new Error('Moyasar provider not yet implemented. Use "mock" for development.')
    case 'stripe':
      throw new Error('Stripe provider not yet implemented. Use "mock" for development.')
    case 'checkout_com':
      throw new Error('Checkout.com provider not yet implemented. Use "mock" for development.')
    default:
      throw new Error(`Unknown payment provider type: ${type}`)
  }

  instances.set(type, provider)
  return provider
}

export function resetPaymentProviderFactory(): void {
  instances.clear()
}

export function getDefaultPaymentProviderType(): PaymentProviderType {
  const envType = typeof import.meta !== 'undefined'
    ? (import.meta as { env?: Record<string, string> }).env?.VITE_PAYMENT_PROVIDER
    : undefined
  if (envType === 'hyperpay' || envType === 'moyasar' || envType === 'stripe' || envType === 'checkout_com') {
    return envType
  }
  return 'mock'
}

export function getDefaultPaymentProvider(): PaymentProvider {
  return createPaymentProvider(getDefaultPaymentProviderType())
}

import { supabase } from '../supabaseClient'
import type { FavoriteRow } from '../types'

export interface CreateFavoriteInput {
  destination: string
  notes?: string
}

export const favoriteRepository = {
  async create(input: CreateFavoriteInput): Promise<FavoriteRow | null> {
    const { data, error } = await supabase
      .from('favorites')
      .insert(input)
      .select()
      .maybeSingle()
    if (error) throw error
    return data
  },

  async listByUser(): Promise<FavoriteRow[]> {
    const { data, error } = await supabase
      .from('favorites')
      .select('*')
      .order('created_at', { ascending: false })
    if (error) throw error
    return data ?? []
  },

  async delete(id: string): Promise<boolean> {
    const { error } = await supabase.from('favorites').delete().eq('id', id)
    if (error) throw error
    return true
  },

  async deleteByDestination(destination: string): Promise<boolean> {
    const { error } = await supabase
      .from('favorites')
      .delete()
      .eq('destination', destination)
    if (error) throw error
    return true
  },

  async exists(destination: string): Promise<boolean> {
    const { data, error } = await supabase
      .from('favorites')
      .select('id')
      .eq('destination', destination)
      .maybeSingle()
    if (error) throw error
    return data !== null
  },
}
